// export default ViewStats

import React, { useEffect, useState } from "react";

function ViewStats() {
  const api_url = "/api";
  const [views, setViews] = useState([]);

  async function getViews() {
    try {
      const response = await fetch(`${api_url}/getViews`);
      const data = await response.json();

      if (!response.ok) {
        throw new Error(data.message || "Failed to fetch views");
      }

      setViews(data.views);
    } catch (error) {
      console.error("Failed to fetch views:", error);
    }
  }

  useEffect(() => {
    getViews();
  }, []);

  // Count page views
  const homeViews = views?.filter(view => view.type === "HomePage").length;
  const paymentViews = views?.filter(view => view.type === "PaymentPage").length;
  const cartViews = views?.filter(view => view.type === "cartPage").length;
  const products = views?.filter(view =>view.type === "ProductPage").length;

  // Count product views
  const productViews = {};

  views.forEach(view => {
    if (view.type === "ProductPage") {
      productViews[view.name] = (productViews[view.name] || 0) + 1;
    }
  });

  return (
    <div className="flex one column gap">

      <div className="flex one center">
        <div className="flex one center">Home Page</div>
        <div className="flex one center">{homeViews}</div>
      </div>

      <div className="flex one center">
        <div className="flex one center">Payment Page</div>
        <div className="flex one center">{paymentViews}</div>
      </div>

      <div className="flex one center">
        <div className="flex one center">Cart Page</div>
        <div className="flex one center">{cartViews}</div>
      </div>

      <div className="flex five column overflow">
        <h3 className="center">Product Views</h3>

        {Object.keys(productViews).length === 0 ? (
          <div className="center">No product views </div>
        ) : (
          Object.entries(productViews).map(([product, count]) => (
            <div className="flex one center" key={product}>
              <div className="flex one center">{product}</div>
              <div className="flex one center">{count}</div>
            </div>
          ))
        )}
      </div>

    </div>
  );
}

export default ViewStats;
